from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find a uniform separator that splits the grid into equal-sized panels.
    splits = []
    for r in range(h):
        if len(set(grid[r])) == 1 and r > 0 and h-r-1 == r:
            splits.append(('h', r))
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid) and c > 0 and w-c-1 == c:
            splits.append(('v', c))
    if not splits:
        raise ValueError('no equal-panel separator')
    orient, k = splits[0]
    if orient == 'h':
        a, b = grid[:k], grid[k+1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    fill = Counter(x for row in a for x in row if x in common).most_common(1)[0][0]
    return [[3 if a[r][c] == b[r][c] else fill for c in range(len(a[0]))]
            for r in range(len(a))]

